preset.customCSS:
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;600;700&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtbook-font-size로 바꿉니다. */
.rtbook {
  --rtbook-bg-fill: transparent;
  --rtbook-blur: none;
  --rtbook-bg-edge: none;
  --rtbook-font-body: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtbook-font-display: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtbook-font-size: 17px;
  --rtbook-line-height: 1.9;
  --rtbook-para-gap: .9em;
  --rtbook-measure: 36em;
  --rtbook-indent: 1em;
  --rtbook-dialog-weight: 600;
  --rtbook-ornament: "⁂";
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtbook {
  --risu-font-family: var(--rtbook-font-body);
  --FontColorStandard: var(--rtbook-ink);
  --FontColorBold: var(--rtbook-ink);
  --FontColorItalic: var(--rtbook-muted);
  --FontColorItalicBold: var(--rtbook-muted);
  --FontColorQuote1: var(--rtbook-muted);
  --FontColorQuote2: var(--rtbook-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtbook-ink);
  font-family: var(--rtbook-font-body);
  font-size: var(--rtbook-font-size);
  line-height: var(--rtbook-line-height);
}
.rtbook, .rtbook *, .rtbook *::before, .rtbook *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtbook.rtbook { display: block; }
.rtbook__content {
  min-width: 0;
  color: var(--rtbook-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtbook__content .chattext {
  --tw-prose-code: var(--rtbook-ink);
  --tw-prose-pre-code: var(--rtbook-ink);
  --tw-prose-pre-bg: var(--rtbook-tint);
  max-width: none;
  color: var(--rtbook-ink);
  font-size: var(--rtbook-font-size) !important;
  line-height: var(--rtbook-line-height) !important;
}
.rtbook__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtbook-font-size);
  line-height: var(--rtbook-line-height);
}
.rtbook__content p { margin: 0 0 var(--rtbook-para-gap); }
.rtbook__content p:last-child { margin-bottom: 0; }
.rtbook__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtbook-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtbook-ink);
  font-family: var(--rtbook-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtbook__content h1 { font-size: calc(var(--rtbook-font-size) * 1.6); }
.rtbook__content h2 { font-size: calc(var(--rtbook-font-size) * 1.35); }
.rtbook__content h3 { font-size: calc(var(--rtbook-font-size) * 1.15); }
.rtbook__content :is(h4, h5, h6) { font-size: var(--rtbook-font-size); }
.rtbook__content strong { font-weight: 700; }
.rtbook__content em { color: var(--rtbook-muted); }
.rtbook__content mark[risu-mark="quote1"],
.rtbook__content mark[risu-mark="blockquote1"] { color: var(--rtbook-muted); background: transparent; }
.rtbook__content mark[risu-mark="quote2"],
.rtbook__content mark[risu-mark="blockquote2"] {
  color: var(--rtbook-dialog);
  font-weight: var(--rtbook-dialog-weight);
  background: transparent;
}
.rtbook__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtbook-line);
  color: var(--rtbook-muted);
}
.rtbook__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtbook__content li { margin: .25em 0; color: var(--rtbook-ink); }
.rtbook__content li::marker { color: var(--rtbook-muted); }
.rtbook__content a { color: var(--rtbook-accent); text-decoration: underline; }
.rtbook__content hr { border: 0; border-top: 1px solid var(--rtbook-line); margin: 1.5em 0; }
.rtbook__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtbook-ink);
  background: var(--rtbook-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtbook-font-size) * .88);
}
.rtbook__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtbook-ink);
  background: var(--rtbook-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtbook-font-size) * .88);
  line-height: 1.5;
}
.rtbook__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtbook__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtbook__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtbook-ink);
  border-bottom: 1px solid var(--rtbook-line);
  text-align: left;
  vertical-align: top;
}
.rtbook__content th { font-weight: 700; }
.rtbook__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtbook__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtbook-ink) !important;
  background: var(--rtbook-edit-bg) !important;
  border: 1px solid var(--rtbook-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtbook-font-size) !important;
  line-height: var(--rtbook-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtbook__footer {
  --risu-theme-textcolor2: var(--rtbook-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtbook__info, .rtbook__actions { min-width: 0; max-width: 100%; }
.rtbook__info > div, .rtbook__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtbook__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtbook__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtbook__footer button:hover { background: var(--rtbook-tint); }
.rtbook :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtbook-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtbook__portrait { overflow: hidden; background: var(--rtbook-tint); }
.rtbook__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtbook__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtbook-bg-fill);
  -webkit-backdrop-filter: var(--rtbook-blur);
  backdrop-filter: var(--rtbook-blur);
  box-shadow: var(--rtbook-bg-edge);
}

/* 구조: 종이책 */

.rtbook {
  background: var(--rtbook-paper);
  padding: 0 clamp(1rem, 5vw, 3rem);
}
.rtbook__page {
  max-width: var(--rtbook-measure);
  margin: 0 auto;
  padding: 1.4rem 0 1rem;
}
/* 넓은 화면: 페이지 양옆에 책장의 그림자 */
@media (min-width: 900px) {
  .rtbook__page {
    padding-left: clamp(1.5rem, 3vw, 2.5rem);
    padding-right: clamp(1.5rem, 3vw, 2.5rem);
    box-shadow: -14px 0 18px -16px var(--rtbook-gutter), 14px 0 18px -16px var(--rtbook-gutter);
  }
}
.rtbook__name { margin-bottom: .6rem; color: var(--rtbook-muted); font-size: .78em; letter-spacing: .12em; }
/* 캐릭터의 서술은 장이 바뀌듯 구분 기호로 시작합니다. 크기는 화면 폭에 맞춥니다. */
.rtbook--char .rtbook__page::before {
  content: var(--rtbook-ornament);
  display: block;
  margin-bottom: 1.1rem;
  text-align: center;
  color: var(--rtbook-accent);
  font-size: clamp(.95em, 1.6vw, 1.3em);
  letter-spacing: .6em;
}
.rtbook--user .rtbook__page { padding-top: .4rem; padding-bottom: .6rem; }
.rtbook--user .rtbook__name { display: none; }
.rtbook--user .rtbook__content { margin-left: 1.2em; padding-left: .9em; border-left: 2px solid var(--rtbook-line); }
.rtbook--user .rtbook__content .chattext,
.rtbook--user .rtbook__content :is(p, li) { color: var(--rtbook-muted) !important; font-size: calc(var(--rtbook-font-size) * .9) !important; }
.rtbook__content p { text-indent: var(--rtbook-indent); }
.rtbook__footer { margin-top: .5rem; }

.rtbook__footer { opacity: 0; transition: opacity .2s ease; }
.rtbook:hover .rtbook__footer, .rtbook:focus-within .rtbook__footer { opacity: 1; }
@media (hover: none) { .rtbook__footer { opacity: .55; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (세피아) ── */
.rtbook {
  --rtbook-paper: #e9dabb;
  --rtbook-ink: #3b2c1c;
  --rtbook-muted: #7d6748;
  --rtbook-accent: #86583a;
  --rtbook-dialog: #3b2c1c;
  --rtbook-line: #d2bb92;
  --rtbook-tint: #dfca9f;
  --rtbook-edit-bg: #f3e6cb;
  --rtbook-gutter: rgba(80, 50, 20, .14);
}
